                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v: number) => [`${v}%`, ""]} />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="singleFamilyPct"
                    name="1-unit"
                    stackId="1"
                    fill={COLORS.sf}
                    stroke={COLORS.sf}
                  />
                  <Area
                    type="monotone"
                    dataKey="twoToFourPct"
                    name="2???4"
                    stackId="1"
                    fill={COLORS.mid}
                    stroke={COLORS.mid}
                  />
                  <Area
                    type="monotone"
                    dataKey="fivePlusPct"
                    name="5+"
                    stackId="1"
                    fill={COLORS.mf}
                    stroke={COLORS.mf}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
