node --input-type=module -e "
import fs from 'fs';
import { POST_ENTRY } from './artifacts/_housing-post-entry.ts';
const path = 'src/data/posts.ts';
let src = fs.readFileSync(path, 'utf8');
const marker = 'export const samplePosts: Post[] = [';
const idx = src.indexOf(marker);
if (idx < 0) throw new Error('marker missing');
const insertAt = idx + marker.length;
const entry = JSON.stringify(POST_ENTRY, null, 2)
  .replace(/\"content\": \"/, 'content: \`')
  .replace(/\\n/g, '\n');
// Better: serialize manually for template literal content
function serializePost(p) {
  const esc = (s) => s.replace(/\\\\/g, '\\\\\\\\').replace(/\`/g, '\\\\\`').replace(/\$\{/g, '\\\\\${');
  return \`  {
    id: \${JSON.stringify(p.id)},
    slug: \${JSON.stringify(p.slug)},
    title:
      \${JSON.stringify(p.title)},
    excerpt:
      \${JSON.stringify(p.excerpt)},
    category: \${JSON.stringify(p.category)},
    themeId: \${JSON.stringify(p.themeId)},
    imageUrl:
      \${JSON.stringify(p.imageUrl)},
    imageAlt:
      \${JSON.stringify(p.imageAlt)},
    publishedAt: \${JSON.stringify(p.publishedAt)},
    featured: \${p.featured},
    visualization: \${JSON.stringify(p.visualization)},
    layout: \${JSON.stringify(p.layout)},
    content: \\\`\${esc(p.content)}\\\`,
  },\`;
}
const block = '\n' + serializePost(POST_ENTRY) + '\n';
src = src.slice(0, insertAt) + block + src.slice(insertAt);
fs.writeFileSync(path, src);
const words = POST_ENTRY.content.split(/\s+/).length;
const h2 = (POST_ENTRY.content.match(/^## /gm) || []).length;
console.log({ words, h2, ok: words >= 1200 && h2 >= 6 });
"

