type Panel =
  | "national-ratio"
  | "cumulative-gap"
  | "metro-ladder"
  | "metro-scatter"
  | "structure-mix"
  | "region-stack";

type SortMode = "ratio-asc" | "gap-desc" | "permits-desc";

const COLORS = {
