  households: "#b45309",
  ratio: "#0f766e",
  gap: "#dc2626",
  surplus: "#15803d",
  sf: "#0369a1",
  mid: "#ca8a04",
  mf: "#7c3aed",
  ne: "#1e40af",
  mw: "#64748b",
  south: "#ea580c",
  west: "#0d9488",
  accent: "#c2410c",
};

const REGION_LABEL: Record<Exclude<RegionId, "all">, string> = {
  northeast: "Northeast",
  midwest: "Midwest",
  south: "South",
  west: "West",
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
