  if (ratio < 1.0) return "#c2410c";
  if (ratio < HEADLINE.replacementBenchmarkRatio) return "#ca8a04";
  return "#15803d";
}

export function UsHousingPermitsVsHouseholdFormation2026Dashboard() {
  const [panel, setPanel] = useState<Panel>("national-ratio");
