                    dataKey="fivePlusPct"
                    name="5+"
                    stackId="1"
                    fill={COLORS.mf}
                    stroke={COLORS.mf}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title={`Structure mix ${structureLatest.year}`}
            subtitle="Latest-year pie ??? same BPS structure shares."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={100}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {pieData.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v: number) => [`${v}%`, "Share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {panel === "region-stack" && (
        <ChartCard
          title="Regional permit volumes"
          subtitle={`Stacked authorized units (thousands). ${REGION_LABEL.south} still accounts for ~${ANALYTICS.southShareOf2024PermitsPct}% of the ${regionLatest.year} total.`}
