                  formatter={(value, name) => {
                    const n = typeof value === "number" ? value : Number(value);
                    const label = String(name);
                    if (label === "ratio" || label === "Permits / HH") {
                      return [n.toFixed(2), "Permits / HH"];
                    }
                    return [n.toLocaleString(), label];
                  }}
                />
                <Legend />
                <Bar
                  yAxisId="vol"
