                  ]}
                  labelFormatter={(_, payload) =>
                    (payload?.[0]?.payload as { metro?: string } | undefined)?.metro ??
                    ""
                  }
                />
                <Bar dataKey="ratio" name="Permits / HH" radius={[0, 4, 4, 0]}>
                  {metros.map((m) => (
                    <Cell key={m.metro} fill={ratioColor(m.ratio)} />
