            title="Authorized units by structure type"
            subtitle="Share of annual BPS permits ??? multifamily share rose into 2022???23 then eased."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={STRUCTURE_MIX.filter((r) => r.year >= yearFrom || yearFrom === 2015)}
                  margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v: number) => [`${v}%`, ""]} />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="singleFamilyPct"
                    name="1-unit"
                    stackId="1"
                    fill={COLORS.sf}
                    stroke={COLORS.sf}
                  />
                  <Area
                    type="monotone"
                    dataKey="twoToFourPct"
                    name="2???4"
                    stackId="1"
                    fill={COLORS.mid}
                    stroke={COLORS.mid}
                  />
                  <Area
                    type="monotone"
                    dataKey="fivePlusPct"
                    name="5+"
                    stackId="1"
                    fill={COLORS.mf}
                    stroke={COLORS.mf}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title={`Structure mix ${structureLatest.year}`}
            subtitle="Latest-year pie ??? same BPS structure shares."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={100}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {pieData.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
