      )}

      {panel === "region-stack" && (
        <ChartCard
          title="Regional permit volumes"
          subtitle={`Stacked authorized units (thousands). ${REGION_LABEL.south} still accounts for ~${ANALYTICS.southShareOf2024PermitsPct}% of the ${regionLatest.year} total.`}
