  ANALYTICS,
  CUMULATIVE_GAP,
  HEADLINE,
  METRO_LADDER,
  NATIONAL_ANNUAL,
  REGION_PERMITS,
  SOURCE_NOTE,
  STRUCTURE_MIX,
  type RegionId,
} from "@/data/us-housing-permits-vs-household-formation-2026-data";

type Panel =
  | "national-ratio"
  | "cumulative-gap"
  | "metro-ladder"
  | "metro-scatter"
  | "structure-mix"
  | "region-stack";

type SortMode = "ratio-asc" | "gap-desc" | "permits-desc";

const COLORS = {
  permits: "#1e3a5f",
  households: "#b45309",
  ratio: "#0f766e",
  gap: "#dc2626",
  surplus: "#15803d",
  sf: "#0369a1",
  mid: "#ca8a04",
  mf: "#7c3aed",
  ne: "#1e40af",
  mw: "#64748b",
  south: "#ea580c",
  west: "#0d9488",
  accent: "#c2410c",
};

const REGION_LABEL: Record<Exclude<RegionId, "all">, string> = {
  northeast: "Northeast",
  midwest: "Midwest",
  south: "South",
  west: "West",
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ratioColor(ratio: number): string {
  if (ratio < 0.7) return "#b91c1c";
  if (ratio < 1.0) return "#c2410c";
  if (ratio < HEADLINE.replacementBenchmarkRatio) return "#ca8a04";
  return "#15803d";
