                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="singleFamilyPct"
                    name="1-unit"
                    stackId="1"
                    fill={COLORS.sf}
                    stroke={COLORS.sf}
                  />
                  <Area
                    type="monotone"
                    dataKey="twoToFourPct"
                    name="2???4"
                    stackId="1"
                    fill={COLORS.mid}
                    stroke={COLORS.mid}
