    console.error("Smoke test timed out ?????? dashboard likely stuck on loading or JS error.");
    console.error("Debug: npx tsx scripts/test-all-costs.ts && node scripts/debug-smoke.mjs");
    console.error(err.message);
  } else {
    console.error(err);
  }
  process.exit(1);
